#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * rule_key: host-safety-compliance
 * rule_id: 0f9bc00f-449b-450e-b341-df55872046e5
 * statement: 禁止生成鼓励自伤、自杀、暴力、未成年人不当内容、赌博、色情等违规输出，无论用户身份或意图。
 * trae_event: UserPromptSubmit
 * matcher: (空，UserPromptSubmit 不支持 matcher)
 *
 * 场景发散设计结论：
 *
 * 1. 解构触发条件：
 *    - "自伤/自杀"包含：自残、自杀、伤害自己、不想活了、结束生命
 *    - "暴力"包含：伤害他人、攻击、殴打、凶杀、虐待
 *    - "未成年人不当内容"包含：儿童、未成年、小学生、中学生 + 不当/敏感关键词
 *    - "赌博"包含：赌钱、博彩、下注、赌场
 *    - "色情"包含：性、裸体、性行为、成人内容
 *
 * 2. 场景分级：
 *    - critical（必须拦截）：prompt 含明确的违规关键词
 *    - lightweight（提醒）：prompt 含边界词但可能是正常语境（如"攻击某个技术问题"中的"攻击"）
 *    - skip（不触发）：prompt 无任何敏感关键词
 *
 * 3. 边界情况：
 *    - 技术语境中的"攻击"（如"攻击这个 bug"）→ skip
 *    - 教育性质的讨论（如"如何防止未成年人接触不当内容"）→ lightweight
 *    - 用户明确是安全测试人员 → 需要额外判断（当前不处理，由人工审核）
 *
 * 4. shouldRun 设计：
 *    - 检查 prompt 是否含 CRITICAL_KEYWORDS（自杀、自残、儿童色情等严重违规词）
 *    - 检查 prompt 是否含边界词但可能是技术语境（如"攻击"）
 *    - 技术语境需要判断：前后是否有"bug"、"漏洞"、"系统"等技术词
 *
 * 5. run 检查逻辑：
 *    - 如果含 critical 级关键词，直接 REJECT
 *    - 如果含边界词但判定为技术语境，PASS
 */

import { runHook, getCwd } from "./_lib.mjs";

// 严重违规关键词（直接拦截）
const CRITICAL_KEYWORDS = [
  // 自伤/自杀
  "自杀", "suicide", "自残", "self-harm", "不想活", "结束生命", "kill myself",
  // 儿童/未成年人敏感
  "儿童色情", "child porn", "未成年人性", "未成年裸",
  // 严重暴力
  "杀人", "murder", "凶杀", "大规模杀戮", "mass shooting",
  // 非法赌博
  "赌钱", "gambling", "博彩", "地下赌场",
  // 极端色情
  "强奸", "rape", "性侵", "sexual assault"
];

// 边界关键词（需要判断语境）
const BORDERLINE_KEYWORDS = [
  "攻击", "attack", "伤害", "harm", "暴力", "violence",
  "打", "hit", "杀", "kill", "虐待", "abuse",
  "赌", "bet", "色情", "porn", "性", "sex"
];

// 技术语境关键词（用于判断边界词是否为技术语境）
const TECH_CONTEXT_KEYWORDS = [
  "bug", "漏洞", "vulnerability", "系统", "system", "代码", "code",
  "测试", "test", "攻击面", "attack surface", "安全", "security",
  "性能", "performance", "问题", "problem", "error", "错误"
];

// 判断是否应该触发
function shouldRun(context) {
  const prompt = (context.userPrompt ?? "").toLowerCase();

  // 1. 检查是否含严重违规关键词
  const hasCritical = CRITICAL_KEYWORDS.some(kw => prompt.includes(kw.toLowerCase()));
  if (hasCritical) return true;

  // 2. 检查是否含边界关键词
  const hasBorderline = BORDERLINE_KEYWORDS.some(kw => prompt.includes(kw.toLowerCase()));
  if (!hasBorderline) return false;

  // 3. 如果有边界词，检查是否为技术语境
  const hasTechContext = TECH_CONTEXT_KEYWORDS.some(kw => prompt.includes(kw.toLowerCase()));
  if (hasTechContext) return false; // 技术语境，不拦截

  // 4. 边界词且非技术语境，触发
  return true;
}

// 执行检查
function run(context) {
  const prompt = context.userPrompt ?? "";
  const promptLower = prompt.toLowerCase();

  // 找出匹配的关键词
  const matchedCritical = CRITICAL_KEYWORDS.filter(kw => promptLower.includes(kw.toLowerCase()));
  const matchedBorderline = BORDERLINE_KEYWORDS.filter(kw => promptLower.includes(kw.toLowerCase()));

  if (matchedCritical.length > 0) {
    return {
      action: "REJECT",
      reason: `安全合规检查未通过：检测到严重违规内容 "${matchedCritical.join(", ")}"`,
      suggestions: [
        "禁止生成鼓励自伤、自杀、暴力、未成年人不当内容、赌博、色情等违规输出",
        "如果您认为这是误判，请联系管理员",
        "如需心理健康支持，请联系专业机构"
      ]
    };
  }

  if (matchedBorderline.length > 0) {
    return {
      action: "REJECT",
      reason: `安全合规检查提醒：检测到敏感内容 "${matchedBorderline.join(", ")}"`,
      suggestions: [
        "请确认您的请求不涉及违规内容",
        "如果是技术语境（如'攻击漏洞'、'性能测试'），请明确说明技术背景",
        "如有疑问，请重新表述您的请求"
      ]
    };
  }

  return { action: "PASS", message: "安全合规检查通过" };
}

// 主流程入口
runHook(shouldRun, run, "UserPromptSubmit");